"""Regenerate test-only amalgamation from the retained pinned upstream files.

No network or production adapter dependency. Changes: remove includes, rename
namespace, make out-of-line definitions inline, replace framework with shim.
Actual filter class declarations/setup/process/tick bodies remain upstream code.
GPL-3.0-or-later; upstream code Copyright 2013-2019 Matt Tytel.
"""
from pathlib import Path
import re

root = Path(__file__).resolve().parents[1]
filters = root / 'src/synthesis/filters'

def clean(text):
    text = re.sub(r'^\s*#(?:include|pragma)[^\n]*\n', '', text, flags=re.M)
    return text.replace('namespace vital {', 'namespace vital_reference {').replace('vital::', 'vital_reference::')

def definitions(text):
    # These source files place out-of-line methods at two-space indentation.
    return re.sub(r'^  (?=(?:void |poly_float |(?:DigitalSvf|LadderFilter|DirtyFilter|DiodeFilter|SallenKeyFilter|CombFilter)::|const ))',
                  '  inline ', text, flags=re.M)

parts = ['// GENERATED by reference/generate.py; DO NOT EDIT.\n'
         '// GPL-3.0-or-later; retained upstream class bodies, see ../LICENSE.\n'
         '#pragma once\n#include "Framework.h"\n']
for name in ['synth_filter', 'one_pole_filter', 'digital_svf', 'ladder_filter', 'dirty_filter', 'diode_filter', 'sallen_key_filter', 'comb_filter']:
    parts.append(clean((filters / (name + '.h')).read_text()))
for name in ['digital_svf', 'ladder_filter', 'dirty_filter', 'diode_filter', 'sallen_key_filter', 'comb_filter']:
    parts.append(clean(definitions((filters / (name + '.cpp')).read_text())))
synth = (filters / 'synth_filter.cpp').read_text()
start = synth.index('  void SynthFilter::FilterState::loadSettings(')
end = synth.index('  SynthFilter* SynthFilter::createFilter', start)
parts.append('namespace vital_reference {\nconstexpr float kMinDriveGain=0, kMaxDriveGain=36;\n'
             'inline const SynthFilter::CoefficientLookup SynthFilter::coefficient_lookup_;\n'
             + clean(definitions(synth[start:end])) + '}\n')
formant = (filters / 'formant_filter.cpp').read_text()
start = formant.index('  namespace {')
end = formant.index('  FormantFilter::FormantFilter', start)
# Only the table selector depends on this constant; no graph/engine is needed.
parts.append('namespace vital_reference {\nstruct FormantFilter {static constexpr int kNumFormantStyles=2;};\n'
             + clean(formant[start:end]) + '}\n')
parts.append('#undef force_inline\n#undef JUCE_LEAK_DETECTOR\n#undef VITAL_ASSERT\n')
(root / 'reference/Upstream.h').write_text('\n'.join(parts), newline='\n')
print('Generated reference/Upstream.h from pinned class source')
